<?php
return [
    'up' => function (PDO $db): void {
        $id = match ($db->getAttribute(PDO::ATTR_DRIVER_NAME)) {
            'mysql' => 'INT AUTO_INCREMENT PRIMARY KEY',
            'pgsql' => 'INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY',
            'sqlite' => 'INTEGER PRIMARY KEY AUTOINCREMENT',
        };
        $db->exec("CREATE TABLE users (
            id {$id}, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE,
            password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'Admin',
            is_active BOOLEAN NOT NULL DEFAULT TRUE, session_version INTEGER NOT NULL DEFAULT 1,
            created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL
        )");
        $db->exec('CREATE TABLE password_resets (user_id INTEGER PRIMARY KEY, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at BIGINT NOT NULL)');
    },
    'down' => function (PDO $db): void { $db->exec('DROP TABLE password_resets'); $db->exec('DROP TABLE users'); },
];
